<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {RefreshCw} from 'lucide-vue-next'
import {api,type ModelCenterInfo,type ModelStatistics} from '../api'
import ModelCatalogEditor from '../components/ModelCatalogEditor.vue'
import {roleLabels} from '../model-catalog'
import {useAppStore} from '../store'
const store=useAppStore(),info=ref<ModelCenterInfo|null>(null),statistics=ref<ModelStatistics|null>(null),editor=ref<InstanceType<typeof ModelCatalogEditor>|null>(null)
const busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),days=ref(30),globalScope=ref(false)
const rows=computed(()=>statistics.value?.models||[]),attempts=computed(()=>rows.value.reduce((sum,row)=>sum+row.attempts,0)),reported=computed(()=>rows.value.reduce((sum,row)=>sum+row.reported_calls,0)),tokens=computed(()=>reported.value?rows.value.reduce((sum,row)=>sum+(row.reported_total_tokens||0),0):null)
let statsAttempt=0
async function loadStats(){const attempt=++statsAttempt;try{const value=await api.modelStatistics(days.value,globalScope.value);if(attempt===statsAttempt)statistics.value=value}catch(e:any){if(attempt===statsAttempt)error.value=e.message}}
async function load(){loading.value=true;error.value='';try{info.value=await api.modelCenter();store.capabilities=await api.capabilities();if(!info.value.can_manage)globalScope.value=false;await Promise.all([loadStats(),editor.value?.load()])}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function catalogSaved(){try{info.value=await api.modelCenter();store.capabilities=await api.capabilities()}catch(e:any){error.value=e.message}}
watch([days,globalScope],()=>{void loadStats()});onMounted(load)
</script>
<template><section class="documents model-center" :aria-busy="busy||loading"><header class="page-title"><div><small>MODEL OPERATIONS</small><h1>模型中心</h1><p>让配置、可用性与每一次调用都有据可查。</p></div><button class="secondary" :disabled="busy||loading" @click="load"><RefreshCw/>刷新</button></header>
  <p v-if="error" role="alert" class="model-error">{{error}}</p><p v-if="notice" role="status" class="model-notice">{{notice}}</p><p v-if="loading&&!info" role="status">正在读取模型配置…</p>
  <template v-if="info"><ModelCatalogEditor ref="editor" @saved="catalogSaved"/>
  <section class="model-section"><header class="stats-heading"><div><small>USAGE LEDGER</small><h2>调用统计</h2></div><div><label class="sr-only" for="stats-days">统计时间范围</label><select id="stats-days" v-model.number="days"><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="90">最近 90 天</option></select><label v-if="info.can_manage" class="scope-label"><input v-model="globalScope" type="checkbox"/>全部用户</label></div></header>
    <div class="usage-summary"><div><small>调用尝试</small><strong>{{attempts.toLocaleString()}}</strong></div><div><small>已报告 Token</small><strong>{{tokens==null?'未报告':tokens.toLocaleString()}}</strong></div><div><small>用量报告覆盖</small><strong>{{reported}} / {{attempts}} <em>次</em></strong></div></div><p class="muted">包含 Agent 与摘要压缩的成功、失败及未完成尝试。未报告用量保留未知；已报告 Token 只汇总可确认的部分，不代表完整账单。</p>
    <div class="table-wrap"><table><thead><tr><th>模型 / 角色</th><th>成功 / 失败 / 未完成</th><th>降级尝试</th><th>完整 Token 合计</th><th>平均耗时</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.provider}/${row.model_name}/${row.model_role}/${row.model_profile_id}/${row.model_profile_version}`"><td><strong>{{row.model_name}}</strong><small class="provider-name">{{row.provider}} · {{row.model_role?roleLabels[row.model_role]:'旧调用'}}</small><small v-if="row.model_profile_id" class="provider-name">{{row.model_profile_id}} · v{{row.model_profile_version}}</small></td><td>{{row.succeeded}} / {{row.failed}} / {{row.incomplete}}</td><td>{{row.fallback_attempts}}</td><td>{{row.total_tokens==null?'用量不完整':row.total_tokens.toLocaleString()}}</td><td>{{row.average_ms==null?'未知':`${row.average_ms} ms`}}</td></tr><tr v-if="!rows.length"><td colspan="5" class="empty-row">这个范围内还没有调用记录。</td></tr></tbody></table></div>
  </section></template>
</section></template>
<style scoped>
.model-center{max-width:1220px}.configuration-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:22px 0;font-size:13px}.configuration-heading>span{display:flex;align-items:center;gap:8px;color:var(--green)}.configuration-heading small,.muted{color:var(--muted)}.configuration-heading svg{width:17px}fieldset{border:0;padding:0;margin:0;min-width:0}.model-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.model-card{padding:24px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}.model-card header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px}.model-card h2{font-family:'Noto Serif SC',serif;font-size:23px;margin:0}.model-card label,.routing>label:not(.fallback){display:grid;gap:9px;font-size:12px;margin:15px 0}.model-card .switch-label{display:flex;align-items:center;gap:8px;margin:0}input:not([type=checkbox]),select{min-width:0;max-width:100%;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:5px;padding:11px;font:inherit}.routing{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 20px;margin:12px 0}.fallback{grid-column:1/-1;display:flex;align-items:center;gap:10px;font-size:13px;padding:12px 0}.muted{font-size:12px;line-height:1.8}.model-error{color:var(--red);font-size:13px}.model-notice{padding:13px;background:var(--green2);color:var(--green);font-size:13px}.model-section{border-top:1px solid var(--line);margin-top:34px;padding-top:28px}.model-section header small{letter-spacing:.13em;color:var(--green);font-size:10px}.model-section h2{font-family:'Noto Serif SC',serif;font-size:22px;margin:8px 0}.health-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.health-grid article{display:flex;flex-direction:column;align-items:flex-start;gap:12px;padding:18px;border:1px solid var(--line);border-radius:7px}.health-grid article>div{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.health-grid small{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.health{font-size:11px;color:var(--muted)}.health.available{color:var(--green)}.health.unavailable,.health.not_configured{color:var(--red)}.stats-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}.scope-label{margin-left:14px;font-size:12px}.usage-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:20px 0}.usage-summary>div{border-left:2px solid var(--green);padding:8px 18px}.usage-summary small{color:var(--muted);font-size:11px}.usage-summary strong{display:block;font-size:29px;margin-top:8px;font-weight:500;font-variant-numeric:tabular-nums}.usage-summary em{font-size:12px;font-style:normal;color:var(--muted)}.provider-name{display:block;color:var(--muted);font-size:11px;margin-top:6px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:disabled,fieldset:disabled{opacity:.55}button:disabled{cursor:not-allowed}@media(max-width:760px){.model-grid,.health-grid{grid-template-columns:1fr}.routing{grid-template-columns:1fr}.stats-heading{align-items:flex-start;flex-direction:column}.usage-summary{gap:10px}.usage-summary>div{padding:6px 10px}.usage-summary strong{font-size:21px}.configuration-heading{align-items:flex-start;flex-direction:column}}
</style>
